const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak, Footer, PageNumber
} = require('docx');

// Color palette: refined, premium, feminine-but-professional feel
const NAVY = "1A2740";
const GOLD = "B8945F";
const SOFT_GRAY = "F4F1EC";
const TEXT_DARK = "2A2A2A";
const RULE_GRAY = "CCCCCC";

// Helper: standard body paragraph
const p = (text, opts = {}) => new Paragraph({
  spacing: { after: 160, line: 300 },
  alignment: opts.align || AlignmentType.LEFT,
  children: [new TextRun({ text, size: 22, color: TEXT_DARK, ...opts.run })]
});

// Helper: bullet
const bullet = (text, bold = null) => {
  const runs = [];
  if (bold) {
    runs.push(new TextRun({ text: bold, size: 22, color: TEXT_DARK, bold: true }));
    runs.push(new TextRun({ text: text, size: 22, color: TEXT_DARK }));
  } else {
    runs.push(new TextRun({ text, size: 22, color: TEXT_DARK }));
  }
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { after: 100, line: 300 },
    children: runs
  });
};

// Helper: section heading
const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 200 },
  children: [new TextRun({ text, size: 30, bold: true, color: NAVY })]
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 240, after: 140 },
  children: [new TextRun({ text, size: 26, bold: true, color: NAVY })]
});

const h3 = (text) => new Paragraph({
  spacing: { before: 180, after: 100 },
  children: [new TextRun({ text, size: 22, bold: true, color: GOLD })]
});

// Helper: horizontal rule via paragraph border
const rule = () => new Paragraph({
  spacing: { before: 120, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 1 } },
  children: [new TextRun({ text: "" })]
});

// Cover page elements
const coverSpacer = (n = 1) => Array.from({ length: n }, () => new Paragraph({ children: [new TextRun({ text: "" })] }));

// Build a two-column comparison table
const buildComparisonTable = () => {
  const border = { style: BorderStyle.SINGLE, size: 4, color: RULE_GRAY };
  const borders = { top: border, bottom: border, left: border, right: border };

  const headerCell = (text) => new TableCell({
    borders,
    width: { size: 4680, type: WidthType.DXA },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 140, bottom: 140, left: 160, right: 160 },
    children: [new Paragraph({
      alignment: AlignmentType.LEFT,
      children: [new TextRun({ text, size: 22, bold: true, color: "FFFFFF" })]
    })]
  });

  const bodyCell = (text, shade = null) => new TableCell({
    borders,
    width: { size: 4680, type: WidthType.DXA },
    shading: shade ? { fill: shade, type: ShadingType.CLEAR } : undefined,
    margins: { top: 120, bottom: 120, left: 160, right: 160 },
    children: [new Paragraph({
      children: [new TextRun({ text, size: 22, color: TEXT_DARK })]
    })]
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      new TableRow({ children: [headerCell("What The Luxora Collective Delivers"), headerCell("What One Price Swipes Delivers")] }),
      new TableRow({ children: [
        bodyCell("Warm introductions to vetted, qualified med spa owners processing $40K to $500K+ monthly", SOFT_GRAY),
        bodyCell("Free statement audits for every Luxora client during onboarding", SOFT_GRAY)
      ]}),
      new TableRow({ children: [
        bodyCell("Positioning as the official preferred processing partner inside the Revenue Leak Audit"),
        bodyCell("Custom, transparent pricing based on actual statement analysis, not flat rates")
      ]}),
      new TableRow({ children: [
        bodyCell("Co-branded educational content and joint lead magnet for both audiences", SOFT_GRAY),
        bodyCell("Free equipment for qualified clients, white-glove installation support", SOFT_GRAY)
      ]}),
      new TableRow({ children: [
        bodyCell("Pre-trained owners who understand the value of systems and recurring partnerships"),
        bodyCell("Direct cell-phone access for ongoing support, no 1-800 hold lines")
      ]}),
      new TableRow({ children: [
        bodyCell("Strategic exposure across the Luxora client base, partner network, and content channels", SOFT_GRAY),
        bodyCell("Optional cash discount program that moves processing fees off the owner entirely", SOFT_GRAY)
      ]}),
    ]
  });
};

// Build the compensation table
const buildCompTable = () => {
  const border = { style: BorderStyle.SINGLE, size: 4, color: RULE_GRAY };
  const borders = { top: border, bottom: border, left: border, right: border };

  const headerCell = (text) => new TableCell({
    borders,
    width: { size: 3120, type: WidthType.DXA },
    shading: { fill: NAVY, type: ShadingType.CLEAR },
    margins: { top: 140, bottom: 140, left: 140, right: 140 },
    children: [new Paragraph({
      children: [new TextRun({ text, size: 22, bold: true, color: "FFFFFF" })]
    })]
  });

  const cell = (text, bold = false) => new TableCell({
    borders,
    width: { size: 3120, type: WidthType.DXA },
    margins: { top: 110, bottom: 110, left: 140, right: 140 },
    children: [new Paragraph({
      children: [new TextRun({ text, size: 22, color: TEXT_DARK, bold })]
    })]
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [3120, 3120, 3120],
    rows: [
      new TableRow({ children: [headerCell("Direction"), headerCell("Compensation"), headerCell("Structure")] }),
      new TableRow({ children: [
        cell("Luxora refers a med spa to One Price Swipes", true),
        cell("25% of monthly processing residual"),
        cell("Recurring, paid for the life of the account")
      ]}),
      new TableRow({ children: [
        cell("One Price Swipes refers a merchant to Luxora", true),
        cell("10% of the 90-Day Growth Engine investment"),
        cell("One-time, paid upon contract execution")
      ]}),
      new TableRow({ children: [
        cell("Joint co-marketing initiatives", true),
        cell("Shared 50/50 on direct revenue generated"),
        cell("Per-campaign, agreed in writing in advance")
      ]}),
    ]
  });
};

// ===== Document =====
const doc = new Document({
  creator: "The Luxora Collective",
  title: "Partnership Proposal: The Luxora Collective and One Price Swipes",
  styles: {
    default: { document: { run: { font: "Calibri", size: 22, color: TEXT_DARK } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Calibri", color: NAVY },
        paragraph: { spacing: { before: 360, after: 200 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Calibri", color: NAVY },
        paragraph: { spacing: { before: 240, after: 140 }, outlineLevel: 1 } },
    ]
  },
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 720, hanging: 360 } } }
      }]
    }]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    footers: {
      default: new Footer({
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [
            new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co  |  Page ", size: 18, color: "8A8A8A" }),
            new TextRun({ children: [PageNumber.CURRENT], size: 18, color: "8A8A8A" })
          ]
        })]
      })
    },
    children: [
      // ===== COVER PAGE =====
      ...coverSpacer(5),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 22, bold: true, color: GOLD, characterSpacing: 60 })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 120, after: 120 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 4 } },
        children: [new TextRun({ text: "" })]
      }),
      ...coverSpacer(2),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 240 },
        children: [new TextRun({ text: "Partnership Proposal", size: 44, bold: true, color: NAVY })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 600 },
        children: [new TextRun({ text: "The Revenue Recovery Stack", size: 28, italics: true, color: GOLD })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 120 },
        children: [new TextRun({ text: "Prepared for", size: 20, color: "6A6A6A" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 360 },
        children: [new TextRun({ text: "Brandon", size: 26, bold: true, color: TEXT_DARK }),
                   new TextRun({ text: ", Founder", size: 22, color: TEXT_DARK }),
                   new TextRun({ text: "\nOne Price Swipes", size: 22, color: TEXT_DARK, break: 1 })]
      }),
      ...coverSpacer(2),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 120 },
        children: [new TextRun({ text: "Prepared by", size: 20, color: "6A6A6A" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Bethany", size: 26, bold: true, color: TEXT_DARK }),
                   new TextRun({ text: ", Co-Founder & CEO", size: 22, color: TEXT_DARK }),
                   new TextRun({ text: "\nThe Luxora Collective", size: 22, color: TEXT_DARK, break: 1 })]
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // ===== OPENING LETTER =====
      h1("A Note Before We Begin"),
      p("Brandon,"),
      p("Thank you for the conversation. Beyond the obvious fit between what One Price Swipes does and what our med spa clients actually need, there is something rarer at play here: we both serve owners who are tired of being a line item to companies that do not pick up the phone."),
      p("That alignment matters, and it is the reason this proposal is not a standard referral arrangement. What follows is a structure designed to create real, measurable value for both companies and, more importantly, for the med spa owners we each work with."),
      p("My partner Eric and our technical lead Jacques will meet with you Tuesday at 9:30 a.m. to walk through the operational details. This document gives them a framework to work from and gives you a clear picture of how I see this relationship taking shape."),
      p("With warmth,"),
      p("Bethany", { run: { bold: true } }),
      p("Co-Founder & CEO, The Luxora Collective"),

      // ===== THE OPPORTUNITY =====
      h1("The Opportunity"),
      p("Independent med spas generating between $500K and $2M annually are losing significant revenue every month to processing fees they do not understand and cannot easily audit themselves. In many cases, owners are paying 3% to 6% per transaction without realizing how those rates compare to the market, and they remain locked into providers like Stripe and Square that offer no meaningful support."),
      p("This is not a marketing problem. It is a leak problem, and it sits squarely inside the work The Luxora Collective already does inside the Revenue Leak Audit. The partnership outlined in this document positions One Price Swipes as the dedicated solution to that specific leak, integrated directly into our diagnostic and onboarding workflow."),

      h2("Why This Is Not a Standard Referral Deal"),
      p("Most processing partnerships are transactional: pass the lead, collect a one-time fee, move on. This structure is different by design. We are proposing a fully integrated revenue partnership that ties One Price Swipes into the diagnostic phase of every Luxora engagement, creates a co-branded asset both companies can use to grow their lists, and rewards both sides with recurring revenue tied to long-term client success."),

      // ===== STRATEGIC FIT =====
      h1("Strategic Fit"),
      h2("What Each Side Brings to the Table"),
      buildComparisonTable(),
      new Paragraph({ spacing: { after: 240 }, children: [new TextRun({ text: "" })] }),

      // ===== PROPOSED STRUCTURE =====
      h1("The Proposed Structure"),
      p("The partnership is built on three pillars: integrated diagnostics, two-way referrals, and joint marketing. Each pillar reinforces the others and creates compounding value for both companies over time."),

      h2("Pillar 1: The Integrated Processing & POS Leak Audit"),
      p("One Price Swipes becomes the official processing partner inside the Luxora Revenue Leak Audit. Every new Luxora client receives a complimentary statement review during onboarding as part of the standard audit deliverable. This produces a fast, quantifiable win in the first 30 days of every engagement and gives both companies an immediate value proof point with the client."),
      h3("What this looks like in practice:"),
      bullet(" During the Revenue Leak Audit, the Luxora team flags the client's current processing setup as a potential leak source.", "Step 1."),
      bullet(" The client's most recent processing statement is forwarded to One Price Swipes for a no-cost analysis.", "Step 2."),
      bullet(" One Price Swipes returns a written summary showing actual current cost, projected savings, and recommended structure.", "Step 3."),
      bullet(" The recovered revenue gets reported back to the client as part of the Revenue Leak Audit findings, with One Price Swipes credited as the partner that made the recovery possible.", "Step 4."),
      bullet(" If the client moves forward, the residual structure outlined below begins immediately.", "Step 5."),

      h2("Pillar 2: Two-Way Referral and Compensation"),
      p("This is a true partnership, not a one-way pipeline. Both companies refer business, and both companies earn compensation when those referrals convert. The structure is summarized below and will be formalized in a written partnership agreement."),
      new Paragraph({ spacing: { after: 120 }, children: [new TextRun({ text: "" })] }),
      buildCompTable(),
      new Paragraph({ spacing: { after: 240 }, children: [new TextRun({ text: "" })] }),
      p("A few notes on this structure. The 25% monthly residual to Luxora is paid on processing fees for the life of the account, with terms around churn and clawback to be finalized in the agreement. The 10% referral fee to One Price Swipes is paid on the full 90-Day Growth Engine investment of $9,000, which translates to $900 per closed referral. Joint marketing splits will be agreed in writing on a per-campaign basis before any spend or work is committed."),

      h2("Pillar 3: Joint Co-Marketing Asset"),
      p("To accelerate both pipelines, we propose building a single co-branded lead magnet within the first 60 days of the partnership: a Processing & POS Leak Audit guide that lives on both companies' platforms. Luxora's audience receives it as a value-add from their trusted growth partner. One Price Swipes' audience receives it as credibility through a niche expert. Leads opting in get added to a shared follow-up sequence with clear ownership rules."),
      h3("Additional co-marketing opportunities to explore:"),
      bullet("Joint webinar or workshop for med spa owners on hidden revenue leaks, with both founders presenting"),
      bullet("Guest appearances on each other's podcasts, content channels, and partner spotlights"),
      bullet("Co-branded one-pager for use in sales conversations and partner introductions"),
      bullet("Coordinated launch announcement to both audiences once the partnership is formalized"),

      // ===== CLIENT EXPERIENCE =====
      h1("The Client Experience"),
      p("From the perspective of a med spa owner working with The Luxora Collective, the partnership feels seamless and additive, never bolted on. Here is the experience we are designing for them:"),
      h3("Week 1 of the 90-Day Growth Engine"),
      p("The Revenue Leak Audit identifies processing as a flagged area. The client is told a complimentary statement review is included in their audit and is introduced to One Price Swipes as a trusted Luxora partner."),
      h3("Week 2 to 3"),
      p("One Price Swipes returns a clear, written savings analysis. If meaningful savings exist, the client is given the option to switch. Equipment, installation, and team training are coordinated through both teams, so the client never feels handed off."),
      h3("Week 4 and beyond"),
      p("Recovered processing dollars are reported back as part of the official Luxora Revenue Leak Audit results. The client now has a fast, tangible win to anchor the rest of the engagement and a direct support line with One Price Swipes for any future questions."),

      // ===== INTERNAL VALIDATION =====
      h1("Internal Validation Before We Recommend"),
      p("Before The Luxora Collective recommends One Price Swipes to a single client, we will run our own statement through the audit process. Eric, our CFO, and Jacques, our technical lead, will use the Tuesday 9:30 a.m. meeting to evaluate pricing transparency, contract terms, POS hardware integration, and the operational handoff. This is non-negotiable on our side because our reputation lives or dies by the partners we put in front of our owners."),
      p("Assuming that validation goes well, we move into a written partnership agreement and a soft launch with a small set of current Luxora clients within 30 days."),

      // ===== TIMELINE =====
      h1("Proposed Timeline"),
      bullet(" Eric and Jacques meet with Brandon. Statement review begins for our own business. Open questions surfaced and documented.", "Tuesday, 9:30 a.m. (this week)"),
      bullet(" Internal Luxora review of statement findings, partnership terms, and integration requirements.", "Week 1 to 2"),
      bullet(" Written partnership agreement drafted, reviewed, and signed by both parties.", "Week 3 to 4"),
      bullet(" Soft launch with 3 to 5 current Luxora clients. Process refined based on real-world feedback.", "Week 5 to 8"),
      bullet(" Full integration into the Revenue Leak Audit. Co-branded lead magnet built and launched.", "Week 9 to 12"),
      bullet(" First quarterly partnership review. Performance metrics evaluated. Next-quarter goals set together.", "Month 4"),

      // ===== POINTS TO DISCUSS =====
      h1("Open Questions for Tuesday's Call"),
      p("The following items are flagged for Eric and Jacques to confirm with Brandon during the Tuesday meeting. None of these are deal-breakers, but each one needs a clear answer before we move to a signed agreement."),
      bullet("Residual payment terms: monthly cadence, payment method, and reporting transparency"),
      bullet("Clawback policy: what happens to residuals if a referred client churns within the first 6 or 12 months"),
      bullet("Contract length and exit terms for referred merchants"),
      bullet("POS hardware compatibility with the systems Luxora typically recommends to med spa clients"),
      bullet("Med spa client references available for Luxora to speak with prior to signing the partnership"),
      bullet("Support response time and escalation path for issues that surface after a client switches"),
      bullet("Chargeback handling and any reserve requirements for high-ticket aesthetic transactions"),

      // ===== WHY US =====
      h1("Why The Luxora Collective"),
      p("The Luxora Collective is the premium, done-with-you revenue growth partner for independent med spas generating between $500K and $2M annually. Our flagship 90-Day Growth Engine carries a guarantee of 2x the client's investment in new or recovered revenue within 90 days, or we continue working at no charge until that benchmark is hit."),
      p("We work from the inside out. Before we ever recommend new investment, we run a full Revenue Leak Audit and deliver a Market Blueprint. Only then do we install the Growth Engine: staff sales training, systems that run without the owner in every transaction, memberships, package architecture, AI follow-up, CRM, partnerships, a reputation engine, and a complete lifetime-value framework. Our goal is owner capability and confidence, not dependency on Luxora."),
      p("That philosophy is exactly why One Price Swipes is the right processing partner for our clients. Both companies are built around the belief that the operator should walk away stronger, more informed, and better supported than they were before."),

      // ===== CLOSING =====
      h1("Closing"),
      p("Brandon, the work you are doing matters to the kind of owners we serve. The med spa industry has been underserved by processing companies that hide behind portals and ticket queues, and the owners we work with are ready for a partner who picks up the phone. That is what you built One Price Swipes to be, and that is why this partnership makes sense."),
      p("Eric and Jacques will be ready Tuesday at 9:30 a.m. I will be in Mexico for my son's graduation trip, but they have the full picture and the authority to move things forward. I look forward to hearing how the conversation goes and to building something meaningful with you."),
      ...coverSpacer(1),
      p("With warmth and excitement,"),
      ...coverSpacer(2),
      p("Bethany", { run: { bold: true, size: 26 } }),
      p("Co-Founder & CEO"),
      p("The Luxora Collective"),
      p("theluxoracollective.co", { run: { color: GOLD } }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_One_Price_Swipes_Partnership_Proposal.docx", buffer);
  console.log("Document created successfully");
});

